UPDATE segments SET image = 'data:image/svg+xml;base64,' WHERE id = 's5' AND (image IS NULL OR image = '');
UPDATE segments SET image = 'data:image/svg+xml;base64,' WHERE id = 's6' AND (image IS NULL OR image = '');

DELETE FROM spins WHERE id LIKE 'demo-%';
